# Pure recommendation policy: never prefer a newer empty reinstall snapshot over older creator work.
policy = Path("app/src/main/java/com/framebynavin/app/cloud/CloudRecoveryPolicy.kt")
if policy.exists():
    raise SystemExit(f"{policy}: already exists")
policy.write_text('''package com.framebynavin.app.cloud\n\nobject CloudRecoveryPolicy {\n    fun hasCreatorWork(point: CloudRestorePoint): Boolean =\n        point.projectCount > 0 || point.ideaCount > 0 || point.weeklySlotCount > 0 || point.activeReminderCount > 0\n\n    fun recommended(points: List<CloudRestorePoint>): CloudRestorePoint? {\n        val newestFirst = points.sortedByDescending { it.capturedAtMillis }\n        return newestFirst.firstOrNull(::hasCreatorWork) ?: newestFirst.firstOrNull()\n    }\n}\n''')

test = Path("app/src/test/java/com/framebynavin/app/cloud/CloudRecoveryPolicyTest.kt")
if test.exists():
    raise SystemExit(f"{test}: already exists")
test.parent.mkdir(parents=True, exist_ok=True)
test.write_text('''package com.framebynavin.app.cloud\n\nimport org.junit.Assert.assertEquals\nimport org.junit.Assert.assertFalse\nimport org.junit.Assert.assertTrue\nimport org.junit.Test\n\nclass CloudRecoveryPolicyTest {\n    private fun point(id: String, time: Long, projects: Int = 0, ideas: Int = 0, weekly: Int = 0) =\n        CloudRestorePoint(id, "daily", time, "2026-09-06", "test", projects, ideas, weekly, 0)\n\n    @Test\n    fun newerEmptySnapshot_neverBeatsOlderCreatorWork() {\n        val emptyNewest = point("empty", 300, projects = 0)\n        val useful = point("useful", 200, projects = 4, ideas = 2)\n        assertEquals("useful", CloudRecoveryPolicy.recommended(listOf(emptyNewest, useful))?.id)\n    }\n\n    @Test\n    fun newestMeaningfulSnapshot_winsAmongUsefulCopies() {\n        val old = point("old", 100, projects = 1)\n        val newer = point("newer", 200, ideas = 1)\n        assertEquals("newer", CloudRecoveryPolicy.recommended(listOf(old, newer))?.id)\n    }\n\n    @Test\n    fun allEmptySnapshots_stillReturnNewestWithoutInventingWork() {\n        val old = point("old", 100)\n        val newer = point("newer", 200)\n        assertFalse(CloudRecoveryPolicy.hasCreatorWork(newer))\n        assertEquals("newer", CloudRecoveryPolicy.recommended(listOf(old, newer))?.id)\n        assertTrue(CloudRecoveryPolicy.recommended(emptyList()) == null)\n    }\n}\n''')

